mapper.select:
select chapter_id, project_id, chapter_no, chapter_title, source_text, source_hash, word_count, summary_text, parse_status, pipeline_status, current_bible_version, source_metadata_json from ai_video_chapter where project_id = #{projectId} and del_flag = '0' and chapter_id in
#{chapterId}
order by chapter_id for update

select task_id, project_id, chapter_id, asset_id, task_name, status from ai_video_generation_task where project_id = #{projectId} and (del_flag = '0' or del_flag is null) and chapter_id in
#{chapterId}
order by task_id for update

select asset_id, project_id, chapter_id, asset_name, asset_type, asset_scope, status from ai_video_asset where project_id = #{projectId} and del_flag = '0' and chapter_id in
#{chapterId}
and not (asset_type = 'CHARACTER_REFERENCE' and asset_scope = 'PROJECT') order by asset_id for update

mapper.update:
update ai_video_asset set status = 'ARCHIVED', del_flag = '2', update_by = #{updateBy}, update_time = now() where project_id = #{projectId} and del_flag = '0' and chapter_id in
#{chapterId}
and not (asset_type = 'CHARACTER_REFERENCE' and asset_scope = 'PROJECT')
